WITH kept_keys AS (SELECT id, location FROM departments INTERSECT SELECT id, location FROM departments WHERE dept_name IS NOT NULL), kept_rows AS (SELECT s.* FROM departments s INNER JOIN kept_keys k ON s.id = k.id AND s.location = k.location), base AS (SELECT *, CASE WHEN budget >= 3896000 THEN 'High' WHEN budget >= 1744000 THEN 'Medium' ELSE 'Low' END AS budget_level, COALESCE(dept_name, 'UNKNOWN') AS dept_name_clean FROM kept_rows WHERE location IS NOT NULL AND location IS NOT DISTINCT FROM 'Berlin'), eligible AS (SELECT s.* FROM base s WHERE NOT EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND ch.full_name LIKE '%Mia%')), base_departments AS (SELECT *, ROUND(budget, 0) AS budget_rounded, COALESCE(location, 'NONE') AS location_clean FROM eligible WHERE budget >= 2154000) SELECT location, metric, value FROM (SELECT location, budget, budget_rounded FROM base_departments) src UNPIVOT (value FOR metric IN (budget, budget_rounded));
